effect.shader:
vec4 u_xlat0;
mediump vec2 u_xlat16_0;
float u_xlat1;
float u_xlat3;
float u_xlat5;
void main()
{
    u_xlat16_0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat16_0.xy = u_xlat16_0.xy + u_xlat16_0.xy;
    u_xlat1 = dot(u_xlat16_0.xy, u_xlat16_0.xy);
    u_xlat1 = sqrt(u_xlat1);
    u_xlat1 = u_xlat1 + (-_Radius);
    u_xlat3 = dFdx(u_xlat1);
    u_xlat5 = dFdy(u_xlat1);
    u_xlat3 = abs(u_xlat5) + abs(u_xlat3);
    u_xlat1 = (-u_xlat3) * 0.5 + u_xlat1;
    u_xlat3 = float(1.0) / (-u_xlat3);
    u_xlat1 = u_xlat3 * u_xlat1;
    u_xlat1 = clamp(u_xlat1, 0.0, 1.0);
    u_xlat3 = u_xlat1 * -2.0 + 3.0;
    u_xlat1 = u_xlat1 * u_xlat1;
    u_xlat0.w = u_xlat1 * u_xlat3;
    u_xlat0.x = float(1.0);
    u_xlat0.y = float(1.0);
    u_xlat0.z = float(1.0);
    fragColor = u_xlat0 * vs_COLOR0;
    return;
}
